import{_ as t,o as i,c as a,a2 as s}from"./chunks/framework.NpvCl_7q.js";const k=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"guide/installation.md","filePath":"guide/installation.md","lastUpdated":1792608207000}'),o={name:"guide/installation.md"};function n(d,e,r,l,c,p){return i(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ns</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @triniwiz/nativescript-masonkit</span></span></code></pre></div><p>That is all a plain NativeScript app needs. The native libraries for iOS, Android and Windows ship inside the package.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Minimum</th></tr></thead><tbody><tr><td>NativeScript iOS runtime</td><td>8.0</td></tr><tr><td>NativeScript Android runtime</td><td>8.0</td></tr><tr><td>NativeScript Windows runtime</td><td>9.1</td></tr><tr><td>iOS deployment target</td><td>15.6</td></tr><tr><td>Android <code>minSdk</code></td><td>21</td></tr></tbody></table><p>On Android the plugin pulls in its own Gradle dependencies (including <code>org.nativescript:fontmanager</code> for font loading), so there is no extra setup step.</p><h2 id="load-order-handled-for-you" tabindex="-1">Load order (handled for you) <a class="header-anchor" href="#load-order-handled-for-you" aria-label="Permalink to &quot;Load order (handled for you)&quot;">​</a></h2><p>MasonKit replaces how CSS shorthands such as <code>margin</code>, <code>padding</code>, <code>border-radius</code> and <code>background</code> are split, and adds units like <code>rem</code> and <code>em</code>. For that to apply to your <code>app.css</code>, MasonKit has to load before the stylesheet is parsed.</p><p>The package ships a <code>nativescript.webpack.js</code> that <code>@nativescript/webpack</code> discovers automatically. It inserts <code>@triniwiz/nativescript-masonkit</code> into the bundle entry right before your app entry, so you do not need to import it first yourself.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If you use a custom bundler setup that does not run NativeScript&#39;s webpack plugin discovery, import <code>@triniwiz/nativescript-masonkit</code> as the very first line of your app entry instead.</p></div><h2 id="framework-entry-points" tabindex="-1">Framework entry points <a class="header-anchor" href="#framework-entry-points" aria-label="Permalink to &quot;Framework entry points&quot;">​</a></h2><p>Angular, Vue 3 and Svelte Native have dedicated entry points inside the same package. Each one exposes an <code>installMasonKit()</code> that registers every element for you:</p><table tabindex="0"><thead><tr><th>Flavour</th><th>Import</th><th>Guide</th></tr></thead><tbody><tr><td>Angular</td><td><code>@triniwiz/nativescript-masonkit/angular</code></td><td><a href="/nativescript-mason/frameworks/angular">Angular</a></td></tr><tr><td>Vue 3</td><td><code>@triniwiz/nativescript-masonkit/vue</code></td><td><a href="/nativescript-mason/frameworks/vue">Vue 3</a></td></tr><tr><td>Svelte Native</td><td><code>@triniwiz/nativescript-masonkit/svelte</code></td><td><a href="/nativescript-mason/frameworks/svelte">Svelte Native</a></td></tr></tbody></table><p>React and Solid register elements from the shared element registry (<code>@triniwiz/nativescript-masonkit/elements</code>). See <a href="/nativescript-mason/frameworks/react">React</a> and <a href="/nativescript-mason/frameworks/solid">Solid</a>. Plain XML and TypeScript apps need no registration: see <a href="/nativescript-mason/frameworks/core">Plain NativeScript</a>.</p><h2 id="preflight-optional" tabindex="-1">Preflight (optional) <a class="header-anchor" href="#preflight-optional" aria-label="Permalink to &quot;Preflight (optional)&quot;">​</a></h2><p>By default MasonKit applies browser user-agent defaults: <code>&lt;p&gt;</code> and headings have vertical margins, lists are indented with markers, and so on. If you prefer a clean slate, the way CSS reset or utility-first frameworks expect, turn on <strong>preflight</strong> at startup (it is off by default):</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { View } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@triniwiz/nativescript-masonkit&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">View.preflight </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>With preflight on, every element starts from:</p><ul><li><code>box-sizing: border-box</code></li><li><code>margin: 0</code>, <code>padding: 0</code>, <code>border-width: 0</code></li><li><code>background: transparent</code></li><li><code>list-style: none</code> on <code>&lt;ul&gt;</code> and <code>&lt;ol&gt;</code></li><li><code>display: block</code> on <code>&lt;img&gt;</code></li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Preflight is global to the whole Mason tree. Set it before any MasonKit view is created; changing it later does not restyle views you have already customised.</p></div><h2 id="typescript" tabindex="-1">TypeScript <a class="header-anchor" href="#typescript" aria-label="Permalink to &quot;TypeScript&quot;">​</a></h2><p>The package ships its own typings. Importing it augments NativeScript&#39;s <code>Style</code> with the CSS properties MasonKit adds (<code>display</code>, <code>gridTemplateColumns</code>, <code>gap</code>, <code>lineClamp</code>, <code>maskImage</code>, ...), so <code>view.style.gridTemplateColumns = &#39;repeat(3, 1fr)&#39;</code> type checks.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { View, Text, Img, Scroll } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@triniwiz/nativescript-masonkit&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { Div, P, Span, H1 } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@triniwiz/nativescript-masonkit/web&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>MasonKit&#39;s own widgets (<code>View</code>, <code>Text</code>, <code>Scroll</code>, <code>Img</code>, <code>Button</code>, <code>Input</code>, <code>TextArea</code>, <code>Br</code>, <code>Ul</code>, <code>Ol</code>, <code>Li</code>) come from the package root. The HTML-shaped elements (<code>Div</code>, <code>Section</code>, <code>P</code>, <code>Span</code>, <code>H1</code> to <code>H6</code>, ...) come from <code>/web</code>.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/nativescript-mason/guide/quick-start">Quick start</a></li><li><a href="/nativescript-mason/styling/units">Units</a>: read this before porting existing CSS.</li></ul>`,26)])])}const u=t(o,[["render",n]]);export{k as __pageData,u as default};
